class Solution:
    def kItemsWithMaximumSum(self, numOnes: int, numZeros: int, numNegOnes: int, k: int) -> int:
        take = min(k, numOnes)
        k -= take
        k -= min(k, numZeros)
        return take - min(k, numNegOnes)

