class Solution:
    def kItemsWithMaximumSum(self, numOnes: int, numZeros: int, numNegOnes: int, k: int) -> int:
        ans = 0
        for _ in range(k):
            if numOnes: numOnes -= 1; ans += 1
            elif numZeros: numZeros -= 1
            else: numNegOnes -= 1; ans -= 1
        return ans

