class Solution {
public:
    int kItemsWithMaximumSum(int numOnes, int numZeros, int numNegOnes, int k) {
        int ans = 0;
        for (int i = 0; i < k; i++) {
            if (numOnes) { numOnes--; ans++; }
            else if (numZeros) numZeros--;
            else { numNegOnes--; ans--; }
        }
        return ans;
    }
};

